"""Build source-backed help content. No database access; no credentials or business records."""
import json, re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
# title, route, view permission, purpose, intended operator, actual operating steps, stock/accounts effect, next action, form source
MODULES = [
('Dashboard','/dashboard',None,'See the work and totals you are allowed to see.','All employees','Open Dashboard;Use the project and task links to open the matching lists;Check deadlines and pending work','Viewing this page does not post stock or money. Totals follow your permissions.','Open the record that needs attention.',None),
('Projects','/projects',None,'Keep one site or job and its linked work together.','Project Manager or Admin','Click Create new project;Enter Site / project name, Site address and Project description;Choose Project manager and Project members;Set dates, Priority and Status;Click Create project;Open the saved project to view work and status history','Saving a project creates a job record. Approved orders and deliveries can later change its status and progress automatically.','Create tasks and the required orders.','projects/project-form.tsx'),
('Tasks','/tasks',None,'Tell people what work they must do and track progress.','Managers and assigned employees','Click Create task;Choose the project, departments and team members;Choose an accountable owner who is also assigned;Enter the title, dates and priority;Save the task;Open it and use Update progress or add a comment','Tasks do not post stock or payments. Completed means 100 percent. Reopening requires progress below 100 percent.','Review the project task list.','tasks/task-form.tsx'),
('Departments','/departments',None,'Group employees by the work they do.','Admin','Click Add department;Enter the department details;Click Create department;Open the department to view its people and tasks','No stock or account entry is created. A name must be unique.','Assign employees to the department.','departments/department-form.tsx'),
('Team Members','/team-members','members.view','Create employee access and map people to departments.','Admin within permission limits or Super Admin','Open Team Members;Open the new member form;Enter the employee details and username;Choose the role and primary department;Choose additional departments if needed;Enter a temporary password;Click Create member','No stock or account entry is created. New members must change their temporary password. Deactivation keeps history and revokes sessions.','Ask the employee to sign in and change their password.','members/member-form.tsx'),
('Items','/items','items.view','Maintain the materials the company buys or supplies.','Storekeeper or authorized master-data operator','Open Items;Open the add item form;Enter the item name and Unit;Enter other needed details and save;Open the item to link its brands','Creating an item does not receive material. Stock belongs to each item and brand combination.','Link the correct brand and record stock through an authorized movement.','inventory/item-form.tsx'),
('Brands','/brands','items.view','Keep brand names consistent across materials.','Authorized master-data operator','Open Brands;Open the add brand form;Enter a unique brand name;Save the brand;Open the relevant item to link it','No stock is created by a brand name. Case-insensitive duplicate names are rejected.','Use the item and brand combination on documents.','inventory/brand-form.tsx'),
('Suppliers','/parties?type=supplier','parties.view','Keep the details of people or companies we buy from.','Purchase Team and Accounts Team','Open Suppliers;Open the new party form;Enter the name and contact details;Keep the supplier option selected;Enter address, tax details and payment terms if needed;Save the record','A supplier profile creates no payable. Approved supplier bills create amounts to pay.','Create a Rate Enquiry or Purchase Order.','parties/party-form.tsx'),
('Clients','/parties?type=client','parties.view','Keep the details of people or companies that buy from us.','Sales operator and Accounts Team','Open Clients;Open the new party form;Enter the name and contact details;Keep the client option selected;Enter address and tax details if needed;Save the record','A client profile creates no receivable. Issued Client Invoices create amounts due.','Record a Client PO or prepare a Quotation.','parties/party-form.tsx'),
('Material Planning','/material-planning','mrp.view','Compare project requirements with stock and procurement.','Project Manager or Purchase Team','Open Material Planning;Choose the project;Review the requirements, available stock and shortages;Use the available planning actions only for the required shortage','A plan alone does not receive or issue stock. Reservations hold stock for a project.','Prepare a Requisition for the shortage.',None),
('Requisitions','/purchase-requisitions','pr.view','Ask the purchase team to arrange materials.','Site Engineer or Project Manager','Open Requisitions;Open the new requisition form;Choose the project and required materials;Enter quantities and dates;Save a draft;Submit for approval from the record page','A requisition does not receive stock or create a supplier bill.','After approval, prepare the Rate Enquiry or Purchase Order.',None),
('Rate Enquiries','/rate-enquiries','rfq.view','Ask suppliers for prices and compare their offers.','Purchase Team','Open Rate Enquiries;Open the new enquiry form;Choose the project and suppliers;Add the required item and brand lines;Save the enquiry;Record supplier quotations and compare the rates;Use the award action only after reviewing the chosen offer','An enquiry and supplier quote do not change stock or create a payable.','Review the linked Purchase Order after award.','procurement/rfq-form.tsx'),
('Purchase Orders','/purchase-orders','po.view','Tell a supplier which materials we want to buy.','Purchase Team and authorized approver','Open Purchase Orders;Open the new purchase order form;Select Project and Supplier;Check Deliver to and delivery instructions;Add item and brand lines, quantities, rates and GST;Enter freight and payment terms if needed;Click Create draft PO;Review and submit the draft;An authorized approver reviews the order','A PO alone does not increase stock. Posted Site Receipts receive accepted material. An approved supplier bill records the payable.','Record actual arrival through Site receipts.','procurement/po-form.tsx'),
('Site receipts','/site-receipts','grn.view','Record materials that actually arrived and passed checks.','Site Engineer and Storekeeper','Open Site Receipts in the menu;Find the source under Waiting to be received;Open its receipt action;Enter Received, Damaged and Rejected quantities;Check Receipt date and Received by;Use Save draft to continue later, or submit for verification;An authorized stock operator posts the verified receipt','Posting a supplier GRN increases accepted stock at its receiving location. A draft does not. An internal transfer receipt moves material from transit to destination; it is not a second purchase.','Attach evidence and record or match the Supplier Bill.','stores/grn-form.tsx'),
('Inventory','/stock','items.view','See quantities by item, brand and location.','Storekeeper','Open Inventory;Use Company stock for totals;Use By location to find the material;Use Stock ledger to trace each movement;Use Reservations to review stock held for projects;Use Locations for stores and sites','Only posted movements change balances. Manual adjustments need permission and a reason. Do not enter an adjustment to repeat a GRN.','Investigate any difference using the Stock ledger.','inventory/movement-form.tsx'),
('Supplier Bills','/supplier-bills','bills.view','Record a supplier invoice and the amount we owe.','Accounts Team','Open Supplier Bills;Open the new bill form;Select the project, supplier and Purchase Order where relevant;Enter the supplier invoice number, dates and bill lines;Check taxes and matching differences;Save a draft and submit it;An authorized approver approves the matched bill','Approval creates the payable and updates billed quantities. This version does not receive stock from the bill. Do not add stock a second time after a GRN.','Record the supplier payment and allocate it to this bill.','payables/bill-form.tsx'),
('Quotations','/quotations','so.view','Prepare a price offer for a client.','Sales operator with Sales Order permissions','Open Quotations;Open the new quotation form;Choose the client and project;Add the offer lines and terms;Save and review the quotation;Use the available send, acceptance or conversion actions after checking the details','A quotation does not issue materials or create an invoice receivable. Public quote links grant access to the offer; share them privately.','Create or review the resulting Sales Order.','sales/quotation-form.tsx'),
('Client POs','/client-pos','cpo.view','Record the order a client sends to us.','Project Manager or authorized sales operator','Open Client POs;Open the new client PO form;Choose project and client;Enter the client reference and date;Add agreed lines, quantities, rates and terms;Click Save draft;Review and submit for approval;Attach the original document in the record evidence panel','An active Client PO records the contract. It does not dispatch stock or issue a tax invoice.','Create the linked Sales Order.','sales/cpo-form.tsx'),
('Sales Orders','/sales-orders','so.view','Record what we agreed to supply to the client.','Project Manager or authorized sales operator','Open Sales Orders;Open the new order form;Choose the project and client;Link the Client PO when applicable;Add materials or services and agreed prices;Save a draft and submit it for approval;Use the amendment process for approved changes','A Sales Order alone does not reduce stock. Client-delivery challans update delivered quantities.','Prepare a Challan when materials are ready.','sales/so-form.tsx'),
('Challans','/challans','grn.view','Record dispatch, transfer or return of materials.','Storekeeper','Open Challans;Open the new challan form;Choose the correct movement type and project;Choose the source and destination;Link the relevant Sales Order or Purchase Order where needed;Enter item and brand quantities;Save and review the draft;Dispatch only after checking physical material','Dispatch reduces the source stock. Internal transfers remain in Goods in transit until receipt. Client delivery records supplied quantities. Returns and reversals have separate controlled actions.','Confirm receipt or delivery and keep the signed proof.','stores/challan-form.tsx'),
('Running Bills','/running-bills','rabill.view','Prepare period billing and record what the client certifies.','Project Manager, Site Engineer and Accounts Team','Open Running Bills;Open the new running bill form for the project;Choose the relevant order;Enter current measurements and review previous quantities;Save and submit for internal review;Record client certification through the authorized action','A Running Bill records measured and certified work. The separate Client Invoice creates the receivable. Do not treat certification as cash received.','Prepare the Client Invoice from eligible certified work.',None),
('Client Invoices','/client-invoices','invoice.view','Issue the client bill that asks for payment.','Accounts Team','Open Client Invoices;Open the new invoice form;Choose the project, client and eligible billing source;Review quantities, tax and deductions;Click Create draft invoice;Review and use the authorized issue action','An issued invoice creates a receivable. Draft and cancelled invoices are excluded from live billed totals.','Record client receipts and allocate them to the invoice.','sales/invoice-form.tsx'),
('Payments & Receipts','/payments','payments.view','Record money paid to suppliers or received from clients.','Accounts Team','Open Payments & Receipts;Open the new payment or receipt form;Choose the direction, party and project;Enter Payment date, mode and bank reference;Enter the amount and choose the bills or invoices being settled;Check each allocation and save','Allocated amounts reduce the matching due. Unallocated money is an advance. Recording money does not move stock. Supplier TDS is recorded on the bill; client TDS is entered on the receipt.','Review the document balance and Project Accounts.','payables/payment-form.tsx'),
('Credit / Debit Notes','/notes','bills.view','Record an approved adjustment to a bill or invoice.','Accounts Team','Open Credit / Debit Notes;Open the new note form;Choose the supplier bill or client invoice being adjusted;Enter the reference, date, reason and value;Save and request approval','Approval adjusts the matching balance. A financial note does not physically return stock. Use a material return separately when required.','Review the adjusted due and keep supporting evidence.',None),
('Project Accounts','/accounts','accounts.view','See project commercial totals and outstanding amounts.','Accounts Team, Project Manager and management','Open Project Accounts;Review the required project;Read the help beside each figure;Open underlying documents before correcting a difference','This is an operational sub-ledger. Margin excludes labour and overheads. Received money and allocated invoice settlement are different measures.','Reconcile invoices, receipts, supplier bills and payments.',None),
('Reports','/reports','reports.commercial','Review and export the reports your role can access.','Management and authorized department staff','Open Reports;Choose the report and available filters;Review the matching rows;Use the export option displayed for that report','Exporting does not change stock or accounts. Task Print, Export PDF and WhatsApp are also available on supported task report views.','Check exported totals and share only with authorized people.',None),
('Documents','/documents',None,'Find attachments and their verification status.','Employees within their record permissions','Open Documents;Search by filename or use project and category filters;Open the permitted record or download its file;Upload and version evidence from the owning record panel','Files do not change stock or financial totals. Verified and posted evidence has retention protections.','Have another authorized person verify important evidence.',None),
('Approvals','/approvals','approvals.view','See records waiting for decisions you may make.','Authorized approvers','Open Approvals;Open a pending record;Check quantities, values and evidence;Use the record approval or rejection action with a clear reason','Approval has module-specific effects. You may need another approver when separation of duties is enabled.','Recheck the updated status and downstream work.',None),
('Administration','/settings',None,'Maintain company settings and permitted administration.','Super Admin for company, role and audit settings','Open Administration;Open only the settings your permissions allow;Review the existing values;Save a deliberate change;Review the audit log where permitted','Numbering, approval and tax settings affect later transactions. Do not change business rules without company approval.','Tell affected employees about the agreed change.',None),
]

articles=[]
def add(id,title,category,summary,sections,permission=None,route=None):
    articles.append(dict(id=id,title=title,category=category,summary=summary,sections=[dict(title=k,paragraphs=v if isinstance(v,list) else [v]) for k,v in sections],permission=permission,route=route))

add('getting-started','Getting Started','Getting Started','Learn how to sign in and use the menu.',[
 ('Before you begin','Ask your manager for your work login and the modules you should use. The screen can hide actions your account cannot perform.'),
 ('Sign in',['1. Open the WATCON application.','2. Enter Email or username and Password.','3. Click Sign in.','4. If asked, enter Current password, New password and Confirm new password. Click Update password.']),
 ('Find your work','Use the left menu on a desktop. On a phone, use the navigation button at the top. Open Tasks for your assigned work. Open a record to see its details.'),
 ('Save safely','Check the project, party, item, brand, quantity and date before saving. A draft often needs submission, approval, posting or issuing before it changes totals. Wait for confirmation before trying again.'),
 ('Sign out','Open your account menu and choose Sign out. Do this on shared computers.'),
 ('Verification note','This guide uses current source labels and local tests. Only the sign-in screenshots come from production. Module examples and screenshots use fictional local data. Untested operations are not a promise of a successful transaction.')])

for i,(title,route,perm,purpose,who,steps,effect,next_,form) in enumerate(MODULES):
    id=route.split('?')[0].strip('/')
    if title in ('Clients','Suppliers'): id=title.lower()
    new_buttons={'Team Members':'Add member','Suppliers':'Add supplier','Clients':'Add client','Requisitions':'New requisition','Rate Enquiries':'New enquiry','Purchase Orders':'New purchase order','Supplier Bills':'Enter supplier bill','Client POs':'New client PO','Sales Orders':'New sales order','Challans':'New challan','Running Bills':'New running bill','Client Invoices':'New invoice'}
    if title in new_buttons:
        steps=re.sub(r'Open the (?:new|add) [^;]*form',f'Click {new_buttons[title]}',steps,count=1)
    save_buttons={'Suppliers':'Create party','Clients':'Create party','Rate Enquiries':'Save enquiry','Sales Orders':'Save draft','Challans':'Save challan','Running Bills':'Save draft','Supplier Bills':'Save draft','Client POs':'Save draft','Payments & Receipts':'Record payment or Record receipt, according to the chosen direction'}
    if title=='Running Bills': form='sales/ra-ui.tsx'
    if title=='Credit / Debit Notes': form='payables/note-ui.tsx'
    labels=[]
    if form and (ROOT/'src/components'/form).exists():
        text=(ROOT/'src/components'/form).read_text(encoding='utf-8')
        labels=list(dict.fromkeys(re.findall(r'label="([^"]+)"',text)))
    meanings={'Project':'The job or site this record belongs to.','Supplier':'The company we buy from.','Client':'The customer we supply.','Site / project name':'A short name employees recognize.','Site address':'The physical work location.','Project description':'What the job covers.','Project manager':'The person responsible for the job.','Project members':'People who need to work on this job.','Unit':'How the material is counted, such as Bag or Nos.','Priority':'How urgently work needs attention.','Status':'The current stage of the record.','GST on charges %':'Tax rate for freight or other charges.','Freight / other charges (₹)':'Extra cost in addition to the material lines.','Internal remarks (not printed)':'A note for staff, excluded from the printed PO terms.','Supplier invoice no.':'The reference printed on the supplier invoice.','Received by':'The person who checked the delivery.'}
    meanings.update({'Legal / registered name':'The name printed on official tax and registration records.','Code':'The short reference used to find this record.','Type':'Choose whether this party is a client, supplier or both.','GSTIN':'The party’s tax registration number. Copy it from its official records.','PAN':'The party’s permanent tax account number.','State (place of supply)':'The state used to decide the tax treatment. Ask Accounts if unsure.','TDS section':'The tax-deduction category selected by Accounts.','TDS rate %':'The percentage Accounts must withhold as TDS.','IFSC':'The bank branch code used for a bank transfer.','Account number':'The bank account to pay or receive money through. Check it independently.','Payment terms (days)':'The agreed number of days before payment is due.','Credit limit (₹)':'The permitted amount of credit agreed with this party.','Quantity':'The number of units in this transaction.','Project code':'The generated reference for this job.','Bill date':'The date on this running bill.','Work done from':'The first day covered by this bill.','Work done up to':'The last day covered by this bill.','Retention %':'The agreed part of the bill held back by the client.','Mobilisation advance (₹)':'The contract advance to be recovered from later bills.','Advance recovery % per bill':'The agreed rate for deducting that advance from each bill.'})
    fields=[f'{x}: {meanings[x]}' if x in meanings else x for x in labels]
    sections=[('What is this module?',purpose),('Why should I use it?',purpose),('Who should use it?',who+'. Your granted permissions decide which actions you can use.'),('When should I use it?','Use this module when its step in the job is ready. Check the source document and actual material or payment first.'),('How do I open it?',f'Open {title if title != "Site receipts" else "Site Receipts"} from the left menu. Address: {route}.'),('How do I add or operate a record?',[f'{n+1}. {s}.' for n,s in enumerate(steps.split(';'))]),('Important fields',fields or ['Use the displayed project, date, reference, status and search filters where available. Read the help beside each field. This page may be a register rather than a creation form.']),('How do I save?','Use the save or creation button described above. Read validation messages, correct the named field and try again. On a viewing or report page there is nothing to save.'),('How do I view or edit?','Open the record from its list. Use Edit only when it is offered. Approved or posted records may require an amendment, cancellation or reversal instead of an edit.'),('How do I print or download?','Use a PDF, Print or export action only where the page displays one. Documents has authorized attachment downloads. Not every register has its own PDF. See the PDF support list in this guide.'),('What happens after saving?','Read the saved status. Draft records still need the next action described above. Saving is not the same as approval or posting.'),('Does it affect stock or accounts?',effect),('What should I do next?',next_),('Common mistakes to avoid','Do not use another project, brand or party just to make a form save. Do not enter the same physical movement twice. Ask your supervisor before cancelling or reversing a posted record.')]
    if title in save_buttons: sections[7]=('How do I save?',f'Click {save_buttons[title]}. Correct any field named in a validation message. Wait for the saved record and check its status.')
    if title in ['Purchase Orders','Rate Enquiries','Supplier Bills','Quotations','Client POs','Sales Orders','Challans','Running Bills','Client Invoices','Payments & Receipts','Credit / Debit Notes']:
        sections[9]=('How do I print or download?','Open the saved document. Use Preview to check it, Download to save the PDF, or Print to open printing. Where WhatsApp is shown, check the recipient and attach the downloaded PDF before sending. These actions do not approve or post the document.')
    add(id,title,'All Modules',purpose,sections,perm,route)

add('business-workflow','Complete Business Workflow','Step-by-Step Tutorials','Follow material and money from project setup to settlement.',[
 ('Project and tasks','Projects → Team Members and Departments → Tasks → progress updates → project review.'),
 ('Procurement','Material Planning → Requisitions → Rate Enquiries → Purchase Orders → Site receipts → Supplier Bills → Payments & Receipts.'),
 ('Sales and billing','Clients → Client POs or Quotations → Sales Orders → Challans → Running Bills → Client Invoices → Payments & Receipts → Project Accounts.'),
 ('Partial work and returns','Record only quantities actually received, dispatched or measured. Use separate receipts or bills for later quantities. Keep references linked. Use the available reversal or cancellation actions; never erase historical transactions.'),
 ('Stock rule','PO and SO drafts or approvals do not move stock. Supplier GRN posting adds accepted quantities. Challan dispatch moves stock out of the source; internal receipts move transit stock to destination. Supplier bill approval does not add stock in this version.'),
 ('Fictional training example',['Use only the isolated test application. Project: ABC Hotel Swimming Pool Installation. Client: ABC Hotel Training. Supplier: Training Pool Supplies. Material: Pool filter, Training brand, unit Nos.','Purchase 10 filters at ₹1,000 each. With 18% GST and no discount or charges, taxable value is ₹10,000, GST ₹1,800 and bill total ₹11,800. Same-state GST is CGST ₹900 plus SGST ₹900.','Receive 6 filters and then 4. After both supplier GRNs are posted, stock rises by 10. Record the supplier bill for ₹11,800. Stock stays at 10. Pay ₹5,000 and then ₹6,800, allocating both payments. Supplier due becomes zero.','Agree a client order for 10 filters at ₹1,500 each. Taxable value is ₹15,000, GST ₹2,700 and total ₹17,700. Deliver 4 and then 6 through client-delivery challans. Stock falls first to 6, then to zero.','Prepare the eligible running bills and record client certification. Issue matching Client Invoices. Receive ₹7,080 and then ₹10,620 with allocations. Final client due is zero. For this example use no retention, advance recovery, TDS or other deductions.','Expected material margin is ₹5,000 before labour and overheads, excluding GST. Verify project accounts, all tasks and outstanding documents before project closure. This numerical example is a training worksheet; the audit evidence states which workflows were actually executed.'])])

roles=[('Super Admin','SUPER_ADMIN','Review security, access and exceptions.','Review role grants and audit entries.','Review backup and restore evidence with the administrator.'),('Admin','ADMIN','Review project tasks and approval queues within access.','Review inactive people, overdue work and rejected documents.','Review project completeness and permission needs.'),('Project Manager','PROJECT_MANAGER','Review project tasks, shortages, receipts and billing progress.','Review open orders and certified work.','Review project accounts and closure blockers.'),('Site Engineer','SITE_ENGINEER','Record actual arrivals, consumption, measurements and task progress.','Reconcile site material and pending receipts.','Review remaining site work and evidence.'),('Purchase Department','PURCHASE','Review shortages, supplier quotations and pending POs.','Follow up expected deliveries and supplier commitments.','Review supplier performance and open orders.'),('Sales Department','PROJECT_MANAGER','Prepare client offers and review agreed orders using granted so and cpo permissions.','Review pending supply and billing with Accounts.','Review customer commitments. There is no separate SALES system role.'),('Store or Inventory Manager','STOREKEEPER','Check stock by location, dispatches, receipts and transit.','Reconcile stock ledger and reservations.','Review differences and request approved adjustments.'),('Accounts Department','ACCOUNTS','Match bills, issue invoices and allocate payments or receipts.','Reconcile dues, advances and notes.','Review tax records and project accounts with the responsible accountant.'),('Normal Employee','USER','Open assigned Tasks, update progress and add comments.','Review deadlines with the manager.','Review completed work and report access problems.')]
for label,key,d,w,m in roles:
    add('role-'+key.lower()+('-sales' if label=='Sales Department' else ''),label,'Role-wise Guides','Daily, weekly and monthly work.',[('Software role',key+' is the mapped system role. Operational responsibilities do not grant extra permissions.'),('Daily',d),('Weekly',w),('Monthly',m)])

glossary={'Project':'One job or work site.','Client':'A customer who buys materials or services from us.','Supplier':'A company or person we buy from.','Item':'A named material or product.','Brand':'The make of an item.','Rate Enquiry':'A request asking suppliers for their prices.','Purchase Order':'An order we send to a supplier to buy materials.','Client Purchase Order':'An order we receive from our client.','Sales Order':'Our record of the supply agreed with the client.','Supplier Bill':'The supplier invoice we record as money to pay.','GRN':'Goods Receipt Note. In this app use Site Receipts to record and post accepted arrivals.','Challan':'A record of materials sent, transferred or returned. It is not a tax invoice.','Running Bill':'A record of current and earlier measured work for review and client certification.','Inventory':'The material we hold and its movement history.','Available Stock':'Stock that can be issued from the selected location after reservations are considered.','Advance Payment':'Money paid or received before it is allocated to a bill or invoice.','Outstanding Amount':'The part of an approved bill or issued invoice still unsettled.','Receivable':'Money a client still owes us.','Payable':'Money we still owe a supplier.','Billed Amount':'Issued Client Invoice value in Project Accounts.','Unbilled Amount':'Work or supply not yet included in an issued invoice; check the specific report definition.','Partial Payment':'Payment of only part of the amount due.','GST':'Goods and Services Tax. Confirm the rate and state treatment with Accounts.','HSN':'The goods classification code used for tax reporting.','Credit Adjustment':'An approved correction that reduces the relevant amount due.'}
add('glossary','Business Terms Glossary','Business Terms Glossary','Plain meanings for everyday business words.',list(glossary.items()))
add('faq','Frequently Asked Questions','Frequently Asked Questions','Answers to common questions.',[
 ('Why is a menu or button missing?','Your role or the record status may not allow it. Ask the Super Admin to check your permissions. Do not use someone else’s login.'),('Why did a PO not increase stock?','Orders are commitments. Stock increases when accepted supplier material is posted through Site Receipts.'),('Why does my bill not increase stock?','This version uses GRN stock posting. A supplier bill records the amount owed and matching quantities.'),('Why is company stock different from site stock?','Material may be in the warehouse, another site, transit or quarantine. Use By location.'),('Why is payment received different from invoice settlement?','Part of the receipt may still be an advance. Check allocations on the receipt.'),('Can I send a PDF through WhatsApp?','Supported task and document controls open a WhatsApp message or sharing link. Review the recipient and message. Attach a downloaded PDF manually when the control does not attach it.'),('Does Project Accounts show full profit?','No. Its material margin excludes labour and overheads. Do not use it as a complete statutory profit statement.'),('Which PDFs exist?','Commercial builders cover Purchase Order, Requisition, Rate Enquiry, supplier quotation, Site Receipt, Challan, Client PO, Sales Order, client Quotation, Running Bill, Client Invoice, Supplier Bill, Payment and adjustment note. Task reports have a PDF route. A PDF option is not guaranteed for every dashboard, statement or register.')])
add('troubleshooting','Troubleshooting','Troubleshooting','What to do when work cannot continue.',[
 ('Sign-in problem','Check Email or username. Use Forgot your password? if needed. If the account is inactive, contact your administrator.'),('Reset message did not arrive','Check your work email and spam folder. Ask the administrator to check SMTP delivery. A reset form alone does not prove email is configured.'),('Insufficient stock','Check the exact item, brand and source location. Review reservations and receipts. Do not make a false adjustment.'),('Changed by someone else','Refresh the record and review its latest version before trying again.'),('Approval refused','Read the reason. Another approver may be required or the amount may exceed your limit.'),('Upload problem','Use an allowed PDF, image, CSV or XLSX within the configured limit. SVG and executables are not accepted. Keep files free of malware.'),('Network error or no confirmation','Reconnect and reopen the list to check whether the record saved. Avoid repeated payment entries. Tell your supervisor the reference, time and visible error; never send your password.'),('Wrong totals','Check document statuses, project links, returns, cancellations, allocations and notes. Ask Accounts to reconcile the original records before editing anything.')])

for article in articles:
    if article['id']=='business-workflow':
        article['sections'].append({'title':'Practical training in 19 steps','paragraphs':[
            'Use an isolated training application. The trainer needs the required permissions. Have another authorized employee approve records when separation of duties applies. Never share a login.',
            '1. Open Clients. Click Add client. Create a fictional client, or select the existing Acme Developers training record. Use the agreed test state for GST.',
            '2. Open Projects. Click Create new project. Enter ABC Hotel Swimming Pool Installation, a fictional Site address and Project description. Choose the manager and members. Click Create project.',
            '3. Open Team Members. Click Add member to create any missing training employees. Set their departments and temporary passwords. Existing training employees can be reused.',
            '4. Open Tasks. Click Create task. Assign the project, departments, team members and accountable owner. Set a due date. Staff later use Update progress and comments.',
            '5. In Items, create Training pool filter with unit Nos. In Brands, create Training brand. Link the brand from the item page. Use zero opening stock for this exercise.',
            '6. Open Suppliers. Click Add supplier to create a fictional supplier, or use the existing Shree Cement Traders training record. Set its correct test state.',
            '7. Open Rate Enquiries. Click New enquiry. Ask for 10 Training pool filters. Click Save enquiry. Record the supplier offer of ₹1,000 each with 18% GST and compare the offers.',
            '8. Review the awarded Purchase Order. If the enquiry has created one, open that order instead of entering it twice. Otherwise use New purchase order. Set quantity 10, rate ₹1,000 and GST 18%. Review, submit and obtain approval. Stock is still zero.',
            '9. Open Site Receipts. Find the PO under Waiting to be received. Record 6 received with no damage or rejection. Submit receipt, then use Verify & add to stock with the authorized operator. Repeat for the remaining 4. Stock is now 10 at the PO receiving location.',
            '10. Open Supplier Bills. Click Enter supplier bill and select the PO. Copy the supplier invoice reference and date. Check 10 × ₹1,000 plus GST = ₹11,800. Save draft, submit and use Approve for payment. Stock remains 10.',
            '11. Open Inventory. Check Company stock, By location and Stock ledger. Confirm the exact item, brand and receiving location. Do not enter another inward movement for the bill.',
            '12. Open Client POs. Click New client PO. Record the client reference and the same project. Add 10 filters at ₹1,500 and 18% GST. Use zero retention and no advance recovery for this simple exercise. Save draft and obtain approval.',
            '13. Open the Client PO and use Create sales order, or create New sales order with the contract linked. Check 10 filters at ₹1,500. Save draft, submit and obtain approval. Stock is still 10.',
            '14. Open Challans. Use New challan and Deliver to client, with the approved Sales Order and the location that holds the filters. Save challan and Dispatch 4 filters. Repeat for the remaining 6. Keep delivery proof. Stock becomes 6, then zero.',
            '15. Open Running Bills. Use New running bill for the active Client PO. Enter the actual current measurement, review earlier quantities and Save draft. Submit for review, obtain internal approval and record client certification. Use Create invoice on the certified bill, then Create draft invoice and Issue invoice. A fully certified total of 10 gives ₹17,700 including GST.',
            '16. Open the client invoice and use Record receipt. Enter ₹7,080, allocate it to the invoice and save. Later record ₹10,620 against the remaining due. Client due becomes zero. An unallocated receipt is an advance and does not settle the invoice.',
            '17. Open the supplier bill and use Record payment. Pay and allocate ₹5,000, then ₹6,800. Supplier due becomes zero.',
            '18. Open Project Accounts. Check client invoiced/received ₹17,700, supplier billed/paid ₹11,800, receivable zero and payable zero. The material margin is ₹5,000 before labour and overheads. Compare the underlying records if any number differs.',
            '19. Complete the assigned tasks. Review open orders, evidence, transit stock and all balances before closing the job. Fully delivered approved Sales Orders can move project status to Completed automatically; that status alone does not prove every bill is paid.'
        ]})
    if article['id']=='glossary': article['sections'] += [{'title':k,'paragraphs':[v]} for k,v in {'GSTIN':'The tax registration number of a business.','TDS':'Tax deducted at source. Part of a payment is withheld for tax rather than paid directly to the other party.','PAN':'The permanent tax account number used on official records.','IFSC':'The code identifying a bank branch for a transfer.','BOQ':'Bill of Quantities. A list of agreed work or material lines and quantities.','Retention':'An agreed amount the client holds back until the required stage.','Certification':'The client’s confirmation of the quantity or value accepted for billing.'}.items()]
    if article['id']=='getting-started':
        article['sections'].append({'title':'How to get a manual','paragraphs':['Help & User Guide is available to Super Admin in Administration → Help & guide. Other employees should ask their supervisor or Super Admin for a copy of this manual. Help pages and downloads are restricted to Super Admin.']})
        for section in article['sections']:
            if section['title']=='Verification note': section['paragraphs']=['This guide explains the available screens. Use only actions your account allows. Ask your supervisor when a business rule is unclear. Training screenshots use fictional records.']
    if article['id']=='faq':
        for section in article['sections']:
            section['paragraphs']=[p.replace('Rate Enquiry, supplier quotation, Site Receipt','Rate Enquiry, Site Receipt') for p in section['paragraphs']]
    if article['id']=='running-bills':
        article['sections'].append({'title':'Check work before billing','paragraphs':['This version limits a running bill by Client PO quantities. It does not automatically require a linked delivered challan for every claim. Check actual completed work and company policy before submitting a claim. Direct Sales Order invoicing has a different delivered-quantity check.']})
out=ROOT/'src/modules/help/content.json'
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps(articles,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
